#!/usr/bin/env bash
# Removes SpaceSync (Linux) and turns Space Calibrator back on.
# Linux port by Lokinya, generated by AI (Claude, Anthropic). AGPL-3.0, see NOTICE.md.
set -euo pipefail
APP="$HOME/.local/opt/SpaceSync"

if pgrep -x vrserver >/dev/null || pgrep -x vrmonitor >/dev/null; then
  echo "Close SteamVR first, then run this again. / Спершу закрий SteamVR, потім запусти ще раз."
  exit 2
fi

STEAM_CFG=""; VRPATHREG=""
for root in "$HOME/.local/share/Steam" "$HOME/.steam/steam" "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam"; do
  for lib in "$root" $(grep -o '"path"[[:space:]]*"[^"]*"' "$root/steamapps/libraryfolders.vdf" 2>/dev/null | cut -d'"' -f4); do
    if [ -x "$lib/steamapps/common/SteamVR/bin/vrpathreg.sh" ]; then
      VRPATHREG="$lib/steamapps/common/SteamVR/bin/vrpathreg.sh"; STEAM_CFG="$root/config"; break 2
    fi
  done
done

pkill -x SpaceSync 2>/dev/null || true
[ -x "$APP/SpaceSync" ] && "$APP/SpaceSync" -removemanifest || true
[ -n "$VRPATHREG" ] && "$VRPATHREG" removedriver "$APP/driver" >/dev/null || true

if [ -n "$STEAM_CFG" ]; then
  python3 - "$STEAM_CFG" "$APP/spacecalibrator-before.json" <<'PY'
import json, os, sys
cfg, saved = sys.argv[1:]
before = {"enable": True, "autolaunch": {}}
if os.path.exists(saved):
    with open(saved) as f:
        before = json.load(f)

def edit(path, change):
    if not os.path.exists(path):
        return
    with open(path) as f:
        data = json.load(f)
    change(data)
    with open(path, "w") as f:
        json.dump(data, f, indent=3)

edit(os.path.join(cfg, "steamvr.vrsettings"),
     lambda d: d.setdefault("driver_01spacecalibrator", {}).update(enable=before.get("enable", True)))
for key, value in before.get("autolaunch", {}).items():
    edit(os.path.join(cfg, "vrappconfig", key + ".vrappconfig"), lambda d, v=value: d.update(autolaunch=v))
PY
fi

rm -f "$HOME/.local/share/applications/spacesync.desktop"
rm -rf "$APP"
echo "SpaceSync removed, Space Calibrator is back on. / SpaceSync видалено, Space Calibrator знову увімкнено."
echo "Your calibration stays in ~/.local/share/SpaceSync (delete it if you don't need it)."
